    "emp": "AXA",
    "title": "AXA Health Solutions - Compliance Officer",
    "sector": "Compagnie d'assurance & mutuelle",
    "famille": "Risques & Conformité",
    "volet": "cdi-cdd",
    "loc": "Hauts-de-Seine",
